   if(e.code===k.interact)this.interact();if(e.code===k.build)this.has('builder')?this.ui.construction():this.ui.toast('Craft a habitat builder first.');if(e.code===k.reload){if(this.buildPreview){this.buildYaw+=Math.PI/2;}else this.exchangePower();}if(e.code===k.light){if(this.has('light')||this.vehicle){if(this.vehicle)this.vehicle.lights=this.vehicle.lights===false;else this.flash=!this.flash;this.audio.effect('click');}else this.ui.toast('A flashlight is required.');}if(e.code===k.exit){if(this.vehicle)this.exitVehicle();else if(this.inside)this.leaveInterior();}if(e.code===k.defense)this.vehicleDefense();if(e.code===k.grapple)this.grapple();if(e.code===k.silent&&this.vehicle?.type==='cyclops'){this.vehicle.silent=!this.vehicle.silent;this.ui.notify(this.vehicle.silent?'Silent running engaged':'Standard running');}if(e.code==='KeyH')this.ui.controls();if(e.code==='F1')$('hud').style.opacity=$('hud').style.opacity==='0'?'1':'0';if(/^Digit[1-5]$/.test(e.code))this.selectSlot(Number(e.code.slice(-1))-1);
