 consumeTool(amount,id=this.s.selected){if(this.s.mode==='creative')return true;const item=this.s.inventory.find(i=>i.id===id);if(!item)return false;if(item.charge===undefined)return true;if(item.charge<=0){this.ui.notify('Battery depleted · R to exchange');return false;}item.charge=Math.max(0,item.charge-amount);return true;}
 useItem(uid){const item=this.s.inventory.find(i=>i.uid===uid);if(!item)return;const d=ITEMS[item.id];if(d.kind==='food'){for(const k of ['food','water','health'])if(d[k])this.s[k]=clamp(this.s[k]+d[k],0,100);this.s.inventory.splice(this.s.inventory.indexOf(item),1);this.audio.effect('collect');}else if(d.kind==='equipment'){if(!equip(this.s,uid))this.ui.toast('Not enough room to exchange equipment.');else{this.s.oxygen=Math.min(this.s.oxygen,maxOxygen(this.s));this.ui.toast(d.name+' equipped');}}else if(d.kind==='tool'){this.s.selected=item.id;this.setToolModel(item.id);this.refreshHotbar();this.ui.close();}else if(d.kind==='deploy'){this.deploy(item);}else if(d.kind==='module'){const v=this.nearVehicle();if(!v){this.ui.toast('Move within 15m of a vehicle.');return;}if(item.id.includes('Depth')&&!item.id.startsWith(v.type)||['drill','grapple'].includes(item.id)&&v.type!=='prawn'||item.id==='shield'&&v.type!=='cyclops'||item.id==='defense'&&v.type!=='seamoth'){this.ui.toast('This module is incompatible with the vehicle.');return;}const previous=v.modules.find(m=>item.id.includes('Depth')&&m.includes('Depth'));if(v.modules.includes(item.id)){this.ui.toast('That module is already installed.');return;}if(previous){v.modules.splice(v.modules.indexOf(previous),1);this.s.inventory.splice(this.s.inventory.indexOf(item),1);addItem(this.s,previous);}else this.s.inventory.splice(this.s.inventory.indexOf(item),1);v.modules.push(item.id);this.ui.toast(d.name+' installed');}else if(d.kind==='battery')this.exchangePower(item);this.refreshHotbar();}
 dropItem(uid){const index=this.s.inventory.findIndex(i=>i.uid===uid);if(index<0)return;const item=this.s.inventory.splice(index,1)[0],pos=this.player.clone().addScaledVector(this.forward(),2);const drop={uid:this.s.uid++,pos:pos.toArray(),items:[item]};this.s.drops.push(drop);this.syncPersistent();this.refreshHotbar();}
 transfer(uid,from,to){const v=this.s.vehicles.find(v=>v.storage===to);const item=from.find(i=>i.uid===uid);if(v&&item&&!pack([...to,item],v.type==='cyclops'?8:v.modules.includes('storageModule')?6:4,v.type==='cyclops'?8:v.modules.includes('storageModule')?8:4)){this.ui.toast('Vehicle storage full. A storage module expands the compartment.');return;}if(!transfer(this.s,uid,from,to))this.ui.toast('No room in the destination.');else this.audio.effect('collect');}
